import json, os, re, collections, datetime, pathlib

ROOT = pathlib.Path.home() / ".claude" / "projects"
files = sorted(ROOT.rglob("*.jsonl"), key=lambda p: p.stat().st_mtime, reverse=True)[:50]

skills = collections.Counter()          # skill name -> invocations (Skill tool)
slash = collections.Counter()           # /name -> invocations
mcp = collections.Counter()             # mcp__server__tool -> calls
mcp_server = collections.Counter()      # server -> calls
hooks = collections.defaultdict(list)   # (hookName, hookEvent) -> [durationMs]
hook_timeouts = collections.Counter()
denials = collections.Counter()         # pattern -> count
denial_kinds = collections.defaultdict(collections.Counter)
denial_fallback = collections.Counter()
tool_uses = {}                          # tool_use_id -> (name, input)
agents = collections.Counter()

mtimes = []
lines_total = 0

DENY_TEXT = ("The user doesn't want to proceed with this tool use",)
DENY_PREFIX = ("Permission to use", "Permission for this")


def bash_key(cmd):
    if not isinstance(cmd, str):
        return None
    toks = cmd.strip().split()
    if not toks:
        return None
    return " ".join(toks[:2]) if len(toks) > 1 and not toks[1].startswith("-") else toks[0]


for f in files:
    mtimes.append(f.stat().st_mtime)
    try:
        fh = open(f, "r", errors="replace")
    except OSError:
        continue
    with fh:
        for line in fh:
            lines_total += 1
            try:
                o = json.loads(line)
            except Exception:
                continue
            t = o.get("type")
            if t == "assistant":
                for c in (o.get("message") or {}).get("content") or []:
                    if not isinstance(c, dict) or c.get("type") != "tool_use":
                        continue
                    name = c.get("name") or ""
                    inp = c.get("input") or {}
                    tool_uses[c.get("id")] = (name, inp)
                    if name == "Skill":
                        s = inp.get("skill")
                        if isinstance(s, str):
                            skills[s] += 1
                    elif name == "Agent":
                        a = inp.get("subagent_type")
                        if isinstance(a, str):
                            agents[a] += 1
                    elif name.startswith("mcp__"):
                        mcp[name] += 1
                        parts = name.split("__")
                        if len(parts) >= 2:
                            mcp_server[parts[1]] += 1
            elif t == "user":
                content = (o.get("message") or {}).get("content")
                text = ""
                if isinstance(content, str):
                    text = content
                elif isinstance(content, list):
                    for c in content:
                        if isinstance(c, dict):
                            if c.get("type") == "text":
                                text += c.get("text") or ""
                            elif c.get("type") == "tool_result":
                                r = c.get("content")
                                rtext = r if isinstance(r, str) else " ".join(
                                    x.get("text", "") for x in r if isinstance(x, dict)
                                ) if isinstance(r, list) else ""
                                kind = o.get("toolDenialKind")
                                tu = tool_uses.get(c.get("tool_use_id"))
                                is_deny = False
                                fallback = False
                                if kind in ("user-rejected", "permission-rule", "automode-blocked",
                                            "automode-unavailable", "automode-parsing-error"):
                                    is_deny = True
                                elif kind is None and c.get("is_error"):
                                    if any(d in rtext for d in DENY_TEXT) or rtext.startswith(DENY_PREFIX):
                                        is_deny, fallback = True, True
                                if is_deny and tu:
                                    nm, ip = tu
                                    if fallback and nm.startswith("mcp__"):
                                        continue
                                    key = bash_key(ip.get("command")) if nm == "Bash" else nm
                                    if key:
                                        key = f"Bash: {key}" if nm == "Bash" else key
                                        denials[key] += 1
                                        denial_kinds[key][kind or "text-fallback"] += 1
                                        if fallback:
                                            denial_fallback[key] += 1
                for m in re.finditer(r"<command-name>/?([^<]+)</command-name>", text):
                    slash[m.group(1).strip()] += 1
            elif t == "attachment":
                a = o.get("attachment") or {}
                if str(a.get("type", "")).startswith("hook_"):
                    k = (a.get("hookName") or "?", a.get("hookEvent") or "?")
                    d = a.get("durationMs")
                    if isinstance(d, (int, float)):
                        hooks[k].append(d)
                    if a.get("timedOut"):
                        hook_timeouts[k] += 1

fmt = lambda ts: datetime.datetime.fromtimestamp(ts).strftime("%Y-%m-%d")
print(f"WINDOW: {len(files)} sessions, {fmt(min(mtimes))} .. {fmt(max(mtimes))}, {lines_total} lines")
print(f"DAYS: {(max(mtimes)-min(mtimes))/86400:.1f}")
for label, ctr in [("SKILLS(Skill tool)", skills), ("SLASH", slash), ("MCP_TOOL", mcp),
                   ("MCP_SERVER", mcp_server), ("AGENTS", agents)]:
    print(f"\n== {label} ==")
    for k, v in ctr.most_common(40):
        print(f"{v:6d}  {k}")
print("\n== HOOKS ==")
for k, ds in sorted(hooks.items(), key=lambda kv: -len(kv[1])):
    ds2 = sorted(ds)
    med = ds2[len(ds2) // 2]
    print(f"{len(ds):5d} runs  median {med:7.0f}ms  p90 {ds2[int(len(ds2)*0.9)]:7.0f}ms  max {ds2[-1]:7.0f}ms  timeouts={hook_timeouts.get(k,0)}  {k}")
print("\n== DENIALS ==")
for k, v in denials.most_common(40):
    print(f"{v:5d}  {k}   kinds={dict(denial_kinds[k])}  fallback={denial_fallback.get(k,0)}")

